/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;

#pragma scop
  /* By marking px restrict, we assure the compiler there is no aliasing 
     between the read-only vector x and the read-only matrices. */
  const DATA_TYPE * restrict px = x;

#ifdef _OPENMP
#pragma omp parallel for private(j) schedule(static)
#endif
  for (i = 0; i < _PB_N - 7; i += 8) {
    /* Utilizing local scalar accumulators ensures intermediate sums are 
       safely kept in CPU registers, rather than constantly updated in memory. */
    DATA_TYPE t0 = SCALAR_VAL(0.0), y0 = SCALAR_VAL(0.0);
    DATA_TYPE t1 = SCALAR_VAL(0.0), y1 = SCALAR_VAL(0.0);
    DATA_TYPE t2 = SCALAR_VAL(0.0), y2 = SCALAR_VAL(0.0);
    DATA_TYPE t3 = SCALAR_VAL(0.0), y3 = SCALAR_VAL(0.0);
    DATA_TYPE t4 = SCALAR_VAL(0.0), y4 = SCALAR_VAL(0.0);
    DATA_TYPE t5 = SCALAR_VAL(0.0), y5 = SCALAR_VAL(0.0);
    DATA_TYPE t6 = SCALAR_VAL(0.0), y6 = SCALAR_VAL(0.0);
    DATA_TYPE t7 = SCALAR_VAL(0.0), y7 = SCALAR_VAL(0.0);

    /* Hoist row addressing calculations */
    const DATA_TYPE * restrict A0 = &A[i][0];
    const DATA_TYPE * restrict B0 = &B[i][0];
    const DATA_TYPE * restrict A1 = &A[i+1][0];
    const DATA_TYPE * restrict B1 = &B[i+1][0];
    const DATA_TYPE * restrict A2 = &A[i+2][0];
    const DATA_TYPE * restrict B2 = &B[i+2][0];
    const DATA_TYPE * restrict A3 = &A[i+3][0];
    const DATA_TYPE * restrict B3 = &B[i+3][0];
    const DATA_TYPE * restrict A4 = &A[i+4][0];
    const DATA_TYPE * restrict B4 = &B[i+4][0];
    const DATA_TYPE * restrict A5 = &A[i+5][0];
    const DATA_TYPE * restrict B5 = &B[i+5][0];
    const DATA_TYPE * restrict A6 = &A[i+6][0];
    const DATA_TYPE * restrict B6 = &B[i+6][0];
    const DATA_TYPE * restrict A7 = &A[i+7][0];
    const DATA_TYPE * restrict B7 = &B[i+7][0];

#pragma GCC ivdep
#pragma GCC unroll 8
    for (j = 0; j < _PB_N; j++) {
      /* Reading x[j] once avoids repetitive L1 cache access for all 8 rows. */
      DATA_TYPE x0 = px[j];

      t0 += A0[j] * x0;
      t1 += A1[j] * x0;
      t2 += A2[j] * x0;
      t3 += A3[j] * x0;
      t4 += A4[j] * x0;
      t5 += A5[j] * x0;
      t6 += A6[j] * x0;
      t7 += A7[j] * x0;

      y0 += B0[j] * x0;
      y1 += B1[j] * x0;
      y2 += B2[j] * x0;
      y3 += B3[j] * x0;
      y4 += B4[j] * x0;
      y5 += B5[j] * x0;
      y6 += B6[j] * x0;
      y7 += B7[j] * x0;
    }

    /* Consolidate scaling operations efficiently to avoid reloading memory fields. */
    tmp[i]   = t0; y[i]   = alpha * t0 + beta * y0;
    tmp[i+1] = t1; y[i+1] = alpha * t1 + beta * y1;
    tmp[i+2] = t2; y[i+2] = alpha * t2 + beta * y2;
    tmp[i+3] = t3; y[i+3] = alpha * t3 + beta * y3;
    tmp[i+4] = t4; y[i+4] = alpha * t4 + beta * y4;
    tmp[i+5] = t5; y[i+5] = alpha * t5 + beta * y5;
    tmp[i+6] = t6; y[i+6] = alpha * t6 + beta * y6;
    tmp[i+7] = t7; y[i+7] = alpha * t7 + beta * y7;
  }

  /* Tail sequence to process leftover iterations logically and cleanly */
  int tail_start = (_PB_N / 8) * 8;
  for (i = tail_start; i < _PB_N; i++) {
    DATA_TYPE t0 = SCALAR_VAL(0.0), y0 = SCALAR_VAL(0.0);
    const DATA_TYPE * restrict A0 = &A[i][0];
    const DATA_TYPE * restrict B0 = &B[i][0];

#pragma GCC ivdep
    for (j = 0; j < _PB_N; j++) {
      DATA_TYPE x0 = px[j];
      t0 += A0[j] * x0;
      y0 += B0[j] * x0;
    }
    tmp[i] = t0;
    y[i] = alpha * t0 + beta * y0;
  }
#pragma endscop

}


