static
void kernel_gesummv[[gnu::flatten, gnu::noinline, gnu::optimize("fast-math", "unroll-loops")]](
		    int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
