      DATA_TYPE t_tmp2 = SCALAR_VAL(0.0), t_y2 = SCALAR_VAL(0.0);
      DATA_TYPE t_tmp3 = SCALAR_VAL(0.0), t_y3 = SCALAR_VAL(0.0);

