	  t_y0   += B[i_b][j] * xj;

	  t_tmp1 += A[i_b+1][j] * xj;
	  t_y1   += B[i_b+1][j] * xj;

	  t_tmp2 += A[i_b+2][j] * xj;
	  t_y2   += B[i_b+2][j] * xj;

	  t_tmp3 += A[i_b+3][j] * xj;
	  t_y3   += B[i_b+3][j] * xj;
