      y[i_b]     = alpha * t_tmp0 + beta * t_y0;

      tmp[i_b+1] = t_tmp1;
      y[i_b+1]   = alpha * t_tmp1 + beta * t_y1;

      tmp[i_b+2] = t_tmp2;
      y[i_b+2]   = alpha * t_tmp2 + beta * t_y2;

      tmp[i_b+3] = t_tmp3;
      y[i_b+3]   = alpha * t_tmp3 + beta * t_y3;
    }

