    {
      DATA_TYPE t_tmp0 = SCALAR_VAL(0.0), t_y0 = SCALAR_VAL(0.0);

      for (int j = 0; j < _PB_N; j++)
	{
	  DATA_TYPE xj = x[j];
	  t_tmp0 += A[i][j] * xj;
	  t_y0   += B[i][j] * xj;
	}

