#pragma scop
  int n_limit = _PB_N - (_PB_N % 4);
  const DATA_TYPE* restrict px = x;

  /* OpenMP parallelization across the outer loop for multithreading on available cores.
     Schedule is static since the workload is completely uniform across rows. */
  #pragma omp parallel for schedule(static)
  for (i = 0; i < n_limit; i += 4)
    {
      /* Accumulator variables for 4 rows. Using local variables avoids pointer aliasing
         and enables efficient reduction vectorization. */
      DATA_TYPE t0 = SCALAR_VAL(0.0), y0 = SCALAR_VAL(0.0);
      DATA_TYPE t1 = SCALAR_VAL(0.0), y1 = SCALAR_VAL(0.0);
      DATA_TYPE t2 = SCALAR_VAL(0.0), y2 = SCALAR_VAL(0.0);
      DATA_TYPE t3 = SCALAR_VAL(0.0), y3 = SCALAR_VAL(0.0);

      /* Precompute row pointers to assist the compiler in avoiding repeated address calculations */
      const DATA_TYPE* restrict A0 = A[i+0];
      const DATA_TYPE* restrict B0 = B[i+0];
      const DATA_TYPE* restrict A1 = A[i+1];
      const DATA_TYPE* restrict B1 = B[i+1];
      const DATA_TYPE* restrict A2 = A[i+2];
      const DATA_TYPE* restrict B2 = B[i+2];
      const DATA_TYPE* restrict A3 = A[i+3];
      const DATA_TYPE* restrict B3 = B[i+3];

