/* Parallelized worker instance for partial range calculations */
static inline void *gesummv_worker(void *arg) {
    struct gesummv_thread_arg *t = (struct gesummv_thread_arg *)arg;

    // Explicitly scope 'n' to secure against potential loop boundary mappings resolving dynamically
    int n = t->n;  

    ptrdiff_t stride = t->stride;
    DATA_TYPE * restrict A_flat = t->A_flat;
    DATA_TYPE * restrict B_flat = t->B_flat;
    DATA_TYPE * restrict tmp = t->tmp;
    DATA_TYPE * restrict x = t->x;
    DATA_TYPE * restrict y = t->y;
    int end = t->end;
    DATA_TYPE alpha = t->alpha;
    DATA_TYPE beta = t->beta;

    int i = t->start;

    // Outer loop unrolling step factoring independent bounds to eliminate issue latency limits
    for (; i <= end - 4; i += 4) {
        DATA_TYPE * restrict A_row0 = A_flat + i * stride;
        DATA_TYPE * restrict A_row1 = A_flat + (i + 1) * stride;
        DATA_TYPE * restrict A_row2 = A_flat + (i + 2) * stride;
        DATA_TYPE * restrict A_row3 = A_flat + (i + 3) * stride;

        DATA_TYPE * restrict B_row0 = B_flat + i * stride;
        DATA_TYPE * restrict B_row1 = B_flat + (i + 1) * stride;
        DATA_TYPE * restrict B_row2 = B_flat + (i + 2) * stride;
        DATA_TYPE * restrict B_row3 = B_flat + (i + 3) * stride;

        DATA_TYPE t0 = SCALAR_VAL(0.0), y0 = SCALAR_VAL(0.0);
        DATA_TYPE t1 = SCALAR_VAL(0.0), y1 = SCALAR_VAL(0.0);
        DATA_TYPE t2 = SCALAR_VAL(0.0), y2 = SCALAR_VAL(0.0);
        DATA_TYPE t3 = SCALAR_VAL(0.0), y3 = SCALAR_VAL(0.0);

        #pragma GCC ivdep
        for (int j = 0; j < _PB_N; j++) {
            DATA_TYPE xj = x[j];
            t0 += A_row0[j] * xj;
            y0 += B_row0[j] * xj;

            t1 += A_row1[j] * xj;
            y1 += B_row1[j] * xj;

            t2 += A_row2[j] * xj;
            y2 += B_row2[j] * xj;

            t3 += A_row3[j] * xj;
            y3 += B_row3[j] * xj;
        }

        tmp[i]   = t0; y[i]   = alpha * t0 + beta * y0;
        tmp[i+1] = t1; y[i+1] = alpha * t1 + beta * y1;
        tmp[i+2] = t2; y[i+2] = alpha * t2 + beta * y2;
        tmp[i+3] = t3; y[i+3] = alpha * t3 + beta * y3;
    }

    // Residual scalar loops for boundaries unaffected by the step scalar logic
    for (; i < end; i++) {
        DATA_TYPE * restrict A_row = A_flat + i * stride;
        DATA_TYPE * restrict B_row = B_flat + i * stride;
        DATA_TYPE t0 = SCALAR_VAL(0.0), y0 = SCALAR_VAL(0.0);

        #pragma GCC ivdep
        for (int j = 0; j < _PB_N; j++) {
            DATA_TYPE xj = x[j];
            t0 += A_row[j] * xj;
            y0 += B_row[j] * xj;
        }

        tmp[i] = t0;
        y[i] = alpha * t0 + beta * y0;
    }

