}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gesummv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE alpha,
		    DATA_TYPE beta,
		    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		    DATA_TYPE POLYBENCH_2D(B,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
#pragma scop
    int num_threads = 32;
    long total_work = (long)_PB_N * _PB_N;

    // Scale down threading allocations if payload bounds are too minuscule to warrant POSIX API creation overheads
    if (total_work / num_threads < 100000) {
        num_threads = total_work / 100000;
        if (num_threads < 1) num_threads = 1;
    }
    if (num_threads > _PB_N) {
        num_threads = _PB_N;
    }

    if (num_threads <= 1) {
        struct gesummv_thread_arg arg;
        arg.start = 0;
        arg.end = _PB_N;
        arg.n = n;
        arg.stride = (DATA_TYPE *)&A[1] - (DATA_TYPE *)&A[0];
        arg.alpha = alpha;
        arg.beta = beta;
        arg.A_flat = (DATA_TYPE *)&A[0];
        arg.B_flat = (DATA_TYPE *)&B[0];
        arg.tmp = (DATA_TYPE *)&tmp[0];
        arg.x = (DATA_TYPE *)&x[0];
        arg.y = (DATA_TYPE *)&y[0];
        gesummv_worker(&arg);
    } else {
        pthread_t threads[32];
        struct gesummv_thread_arg args[32];

        ptrdiff_t stride = (DATA_TYPE *)&A[1] - (DATA_TYPE *)&A[0];
        DATA_TYPE *A_flat = (DATA_TYPE *)&A[0];
        DATA_TYPE *B_flat = (DATA_TYPE *)&B[0];

        int chunk = _PB_N / num_threads;
        int remainder = _PB_N % num_threads;
        int current_start = 0;

        for (int t = 0; t < num_threads; t++) {
            args[t].start = current_start;
            int current_chunk = chunk + (t < remainder ? 1 : 0);
            args[t].end = current_start + current_chunk;
            args[t].n = n;
            args[t].stride = stride;
            args[t].alpha = alpha;
            args[t].beta = beta;
            args[t].A_flat = A_flat;
            args[t].B_flat = B_flat;
            args[t].tmp = (DATA_TYPE *)&tmp[0];
            args[t].x = (DATA_TYPE *)&x[0];
            args[t].y = (DATA_TYPE *)&y[0];

            current_start += current_chunk;

            // Compute the ultimate chunk straight on the main thread instead of idling upon 'pthread_join'
            if (t == num_threads - 1) {
                gesummv_worker(&args[t]);
            } else {
                pthread_create(&threads[t], NULL, gesummv_worker, &args[t]);
            }
        }

        for (int t = 0; t < num_threads - 1; t++) {
            pthread_join(threads[t], NULL);
        }
    }
#pragma endscop
}


